mapper.select:
SELECT model_code, COUNT(*) AS total_count, COALESCE(SUM(CASE WHEN status = 'SUCCEEDED' THEN 1 ELSE 0 END), 0) AS succeeded_count, COALESCE(SUM(CASE WHEN status = 'SUCCEEDED' THEN image_count ELSE 0 END), 0) AS total_images, COALESCE(SUM(total_cost), 0) AS total_cost, AVG(CASE WHEN status = 'SUCCEEDED' THEN total_elapsed_ms END) AS avg_elapsed_ms FROM t_image_task
user_id = #{userId}
GROUP BY model_code ORDER BY total_cost DESC
